 rows=[('H','ammonia','H','imine',None),('R','1°-amine','R','N-substituted imine','(sec-imine)'),('OH','hydroxylamine','OH','oxime',None),('NH₂','hydrazine','NH₂','hydrazone',None),('NH—C₆H₅','phenyl hydrazine','NH—C₆H₅','phenyl hydrazone',None)]
